  let chars: string[] = [];
  for (let ch: string of word) { chars.push(ch); }
  let n: number = chars.length();
  let s: number = seed;
  let i: number = n - 1;
  while (i > 0) {
    s = s * 1103515245 + 12345;
    if (s < 0) { s = -s; }
    let j: number = s % (i + 1);
    let tmp: string = chars[i];
    chars[i] = chars[j];
    chars[j] = tmp;
    i = i - 1;
  }
  let out: string = "";
  for (let c: string of chars) { out = out + c; }
  if (out === word && n > 1) {
    let first: string = strings.substring(out, 0, 1);
    let rest: string = strings.substring(out, 1, n);
    out = rest + first;
  }
  return out;
}

