  let emptyEntries: LogEntry[] = [];
  return {entries: emptyEntries, draft_cups: "", draft_day: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}







