import * as ui from "std/ui"

@jsonable
class AppState {
  movieList: string;
  c_angle: number;
  c_speed: number;
  c_seed: number;
  c_picked: string;
  c_used: string;
  c_spinning: boolean;
  c_ticks: number;
}

function init(): AppState {
  return {movieList: "", c_angle: 0, c_speed: 0, c_seed: 20261101, c_picked: "", c_used: "", c_spinning: false, c_ticks: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_movieList(state: AppState, value: string): AppState {
  return {movieList: value, c_angle: state.c_angle, c_speed: state.c_speed, c_seed: state.c_seed, c_picked: state.c_picked, c_used: state.c_used, c_spinning: state.c_spinning, c_ticks: state.c_ticks};
}







function c_titles(state: AppState): string[] {
  let out: string[] = [];
  let parts: string[] = strings.split(state.movieList, "\n");
  for (let p: string of parts) {
    let t: string = strings.trim(p);
    if (strings.length(t) > 0) {
      out.push(t);
    }
  }
  return out;
}

function c_isUsed(state: AppState, title: string): boolean {
  let parts: string[] = strings.split(state.c_used, "\n");
  for (let p: string of parts) {
    if (p === title) {
      return true;
    }
  }
  return false;
}

function c_pool(state: AppState): string[] {
  let out: string[] = [];
  for (let t: string of c_titles(state)) {
    if (!c_isUsed(state, t)) {
      out.push(t);
    }
  }
  return out;
}

function c_spin(state: AppState, value: number): AppState {
  if (state.c_spinning) {
    return state;
  }
  let seed: number = math.randomStep(state.c_seed);
  return {c_spinning: true, c_speed: 760 + math.randomBelow(seed, 300), c_seed: seed, c_picked: "", c_ticks: state.c_ticks + 1, movieList: state.movieList, c_angle: state.c_angle, c_used: state.c_used};
}

function c_reset(state: AppState, value: number): AppState {
  return {c_used: "", c_picked: "", c_spinning: false, c_speed: 0, c_angle: 0, c_ticks: state.c_ticks + 1, movieList: state.movieList, c_seed: state.c_seed};
}

function c_frame(state: AppState, elapsedMs: number): AppState {
  if (!state.c_spinning) {
    return state;
  }
  let dt: number = math.min(elapsedMs, 50) / 1000;
  let angle: number = state.c_angle + state.c_speed * dt;
  angle = angle - 360 * math.floor(angle / 360);
  let speed: number = math.max(0, state.c_speed - 200 * dt);
  if (speed > 0) {
    return {c_angle: angle, c_speed: speed, c_ticks: state.c_ticks + 1, movieList: state.movieList, c_seed: state.c_seed, c_picked: state.c_picked, c_used: state.c_used, c_spinning: state.c_spinning};
  }
  let pool: string[] = c_pool(state);
  if (pool.length() === 0) {
    return {c_angle: angle, c_speed: 0, c_spinning: false, c_ticks: state.c_ticks + 1, movieList: state.movieList, c_seed: state.c_seed, c_picked: state.c_picked, c_used: state.c_used};
  }
  let seed: number = math.randomStep(state.c_seed);
  let pick: number = math.randomBelow(seed, pool.length());
  let chosen: string = pool[pick];
  let used: string = state.c_used;
  if (strings.length(used) > 0) {
    used = used + "\n" + chosen;
  } else {
    used = chosen;
  }
  let step: number = 360 / pool.length();
  let target: number = 0 - (pick + 0.5) * step;
  target = target - 360 * math.floor(target / 360);
  return {c_angle: target, c_speed: 0, c_spinning: false, c_seed: seed, c_picked: chosen, c_used: used, c_ticks: state.c_ticks + 1, movieList: state.movieList};
}

function c_tap(state: AppState, p: gfx.Pointer): AppState {
  if (p.phase === "down" || p.phase === "up") {
    return c_spin(state, 0);
  }
  return state;
}

function c_px(a: number, r: number): number {
  return r * math.sin(a * math.pi() / 180);
}

function c_py(a: number, r: number): number {
  return 0 - r * math.cos(a * math.pi() / 180);
}

function c_short(t: string): string {
  if (strings.length(t) > 12) {
    return strings.substring(t, 0, 12);
  }
  return t;
}

function c_draw(state: AppState): gfx.Shape[] {
  let shapes: gfx.Shape[] = [];
  shapes.push(gfx.circle(150, 150, 142, "#1b1030"));
  let pool: string[] = c_pool(state);
  let n: number = pool.length();
  if (n === 0) {
    let empty: gfx.Shape[] = [];
    let j: number = 0;
    while (j < 8) {
      let b0: number = j * 45;
      let b1: number = b0 + 45;
      let tone: string = "#2a1a45";
      if (j % 2 === 1) {
        tone = "#3d2769";
      }
      empty.push(gfx.polygon([0, 0, c_px(b0, 130), c_py(b0, 130), c_px(b0 + 22.5, 130), c_py(b0 + 22.5, 130),
        c_px(b1, 130), c_py(b1, 130)], tone));
      empty.push(gfx.circle(c_px(b0 + 22.5, 104), c_py(b0 + 22.5, 104), 7, "#ffd54a"));
      j = j + 1;
    }
    empty.push(gfx.circle(0, 0, 52, "#1b1030"));
    shapes.push(gfx.group(150, 150, state.c_angle, 1, 1, empty));
    shapes.push(gfx.arc(150, 150, 130, 0, 360, 4, "white"));
    shapes.push(gfx.text(150, 150, 14, "center", "white", "All picked", true));
    shapes.push(gfx.polygon([150, 30, 138, 4, 162, 4], "danger"));
    return shapes;
  }
  let step: number = 360 / n;
  let wheel: gfx.Shape[] = [];
  let i: number = 0;
  while (i < n) {
    let a0: number = i * step;
    let a1: number = a0 + step;
    let tone: string = "#ffd54a";
    if (i % 2 === 1) {
      tone = "#7c4dff";
    }
    wheel.push(gfx.polygon([0, 0, c_px(a0, 130), c_py(a0, 130), c_px(a0 + step / 2, 130), c_py(a0 + step / 2, 130),
      c_px(a1, 130), c_py(a1, 130)], tone));
    let ink: string = "black";
    if (i % 2 === 1) {
      ink = "white";
    }
    wheel.push(gfx.group(c_px(a0 + step / 2, 88), c_py(a0 + step / 2, 88), a0 + step / 2, 1, 1,
      [gfx.text(0, 0, 13, "center", ink, c_short(pool[i]), true)]));
    i = i + 1;
  }
  wheel.push(gfx.circle(0, 0, 20, "#1b1030"));
  shapes.push(gfx.group(150, 150, state.c_angle, 1, 1, wheel));
  shapes.push(gfx.arc(150, 150, 130, 0, 360, 4, "white"));
  shapes.push(gfx.polygon([150, 30, 138, 4, 162, 4], "danger"));
  return shapes;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Random Movie Picker", "NO REPEATS", "Pick a movie you haven't seen yet", ""));
  {
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Movie list", state.movieList, "set_movieList")]));
  }
  {
  let c_poolNow: string[] = c_pool(state);
  let c_left: number = c_poolNow.length();
  let c_total: number = c_titles(state).length();
  sections.push(ui.Section("content", "Reel", "Tap the reel or press Spin", [
    ui.Surface("default", 300, 300, "c_draw", "c_frame", "c_tap"),
    ui.When(state.c_picked !== "", ui.Text("title", "Now showing: " + state.c_picked)),
    ui.When(state.c_picked === "" && !state.c_spinning && c_left === 0 && c_total > 0,
      ui.Text("body", "All movies have been picked. Reset to put them all back.")),
    ui.When(c_total === 0,
      ui.Text("caption", "Add one movie per line in the list above, then spin the reel.")),
    ui.ActionBar("default", [
      ui.Button("primary", "Spin", "c_spin", 0, !state.c_spinning),
      ui.Button("secondary", "Reset", "c_reset", 0, state.c_used !== "" || state.c_spinning)
    ]),
    ui.NumberText("caption", c_left, "", " of " + ui.numberToString(c_total) + " still in the pool", 0)
  ]));
  }
  return ui.AppTheme("playful", "", sections);
}

