  if (n === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let pool: number[] = [];
  let i: number = 0;
  while (i < n) {
    let used: boolean = false;
    for (let u: number of state.c_used) { if (u === i) { used = true; } }
    if (!used) { pool.push(i); }
    i = i + 1;
  }
  if (pool.length() === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let seed: number = state.c_seed + 1;
  let pick: number = pool[math.randomBelow(seed, pool.length())];
  let out: number[] = [];
  for (let u2: number of state.c_used) { out.push(u2); }
  out.push(pick);
  return {c_used: out, c_tonight: pick, c_seed: seed, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7};
}

function c_reset(state: AppState, ignored: number): AppState {
