function rebuildIdeas7(state: AppState, ideas: Idea[], at: number, timePick: number, levelPick: number): AppState {
  return {ideas7: ideas, at7: at, time7: timePick, level7: levelPick, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed};
}

function levels7(state: AppState): string[] {
  let out: string[] = [];
  for (let it: Idea of state.ideas7) {
    let seen: boolean = false;
    for (let l: string of out) { if (l === it.level) { seen = true; } }
    if (!seen && it.level.length() > 0) { out.push(it.level); }
  }
  return out;
}

function timeLimit7(pick: number): number {
  if (pick === 1) { return 5; }
  if (pick === 2) { return 15; }
  if (pick === 3) { return 30; }
  return 100000;
}

function fits7(state: AppState, timePick: number, levelPick: number, index: number): boolean {
  if (index < 0 || index >= state.ideas7.length()) { return false; }
  let it: Idea = state.ideas7[index];
  if (it.minutes > timeLimit7(timePick)) { return false; }
  let levels: string[] = levels7(state);
  if (levelPick > 0 && levelPick <= levels.length()) {
    if (it.level !== levels[levelPick - 1]) { return false; }
  }
  return true;
}

function nextFit7(state: AppState, timePick: number, levelPick: number, startAt: number): number {
  let n: number = state.ideas7.length();
  if (n === 0) { return -1; }
  let start: number = startAt;
  if (start < 0) { start = 0; }
  let k: number = 0;
  while (k < n) {
    let i: number = (start + k) % n;
    if (fits7(state, timePick, levelPick, i)) { return i; }
    k = k + 1;
  }
  return -1;
}

function doneToday7(state: AppState): number {
  let today: number = time.daysSinceEpoch();
  let n: number = 0;
  for (let it: Idea of state.ideas7) { if (it.doneDay === today) { n = n + 1; } }
  return n;
}

function anotherIdea7(state: AppState, ignored: number): AppState {
  let next: number = nextFit7(state, state.time7, state.level7, state.at7 + 1);
  return rebuildIdeas7(state, state.ideas7, next, state.time7, state.level7);
}

function doneIdea7(state: AppState, ignored: number): AppState {
  if (!fits7(state, state.time7, state.level7, state.at7)) { return state; }
  let today: number = time.daysSinceEpoch();
  let out: Idea[] = [];
  let i: number = 0;
  while (i < state.ideas7.length()) {
    let it: Idea = state.ideas7[i];
    if (i === state.at7) {
      out.push({title: it.title, minutes: it.minutes, level: it.level, how: it.how, doneDay: today});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  let marked: AppState = rebuildIdeas7(state, out, state.at7, state.time7, state.level7);
  let n: number = out.length();
  let k: number = 1;
  while (k < n) {
    let j: number = (state.at7 + k) % n;
    if (fits7(marked, state.time7, state.level7, j) && out[j].doneDay !== today) {
      return rebuildIdeas7(state, out, j, state.time7, state.level7);
    }
    k = k + 1;
  }
  return rebuildIdeas7(state, out, nextFit7(marked, state.time7, state.level7, state.at7 + 1), state.time7, state.level7);
}

function pickIdea7(state: AppState, index: number): AppState {
  if (index < 0 || index >= state.ideas7.length()) { return state; }
  return rebuildIdeas7(state, state.ideas7, index, state.time7, state.level7);
}

function setIdeaTime7(state: AppState, index: number): AppState {
  let at: number = state.at7;
  if (!fits7(state, index, state.level7, at)) { at = nextFit7(state, index, state.level7, 0); }
  return rebuildIdeas7(state, state.ideas7, at, index, state.level7);
}

function setIdeaLevel7(state: AppState, index: number): AppState {
  let at: number = state.at7;
  if (!fits7(state, state.time7, index, at)) { at = nextFit7(state, state.time7, index, 0); }
  return rebuildIdeas7(state, state.ideas7, at, state.time7, index);
}

function c_pick(state: AppState, ignored: number): AppState {
  sdk.call("ArkTS.util.generateRandomUUID", [], "c_onRandom");
  let n: number = state.ideas7.length();
  if (n === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let pool: number[] = [];
  let i: number = 0;
  while (i < n) {
    let used: boolean = false;
    for (let u: number of state.c_used) { if (u === i) { used = true; } }
    if (!used) { pool.push(i); }
    i = i + 1;
  }
  if (pool.length() === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let seed: number = state.c_seed + 1;
  let pick: number = pool[math.randomBelow(seed, pool.length())];
  let out: number[] = [];
  for (let u2: number of state.c_used) { out.push(u2); }
  out.push(pick);
  return {c_used: out, c_tonight: pick, c_seed: seed, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7};
}

function c_reset(state: AppState, ignored: number): AppState {
  let empty: number[] = [];
  return {c_used: empty, c_tonight: -1, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_seed: state.c_seed};
}

function c_onRandom(state: AppState, value: string): AppState {
  let n: number = state.ideas7.length();
  if (n === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let pool: number[] = [];
  let i: number = 0;
  while (i < n) {
    let used: boolean = false;
    for (let u: number of state.c_used) { if (u === i) { used = true; } }
    if (!used) { pool.push(i); }
    i = i + 1;
  }
  if (pool.length() === 0) { return {ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_used: state.c_used, c_tonight: state.c_tonight, c_seed: state.c_seed}; }
  let seed: number = state.c_seed;
  let failed: boolean = strings.startsWith(value, "error") || strings.startsWith(value, "declined");
  if (failed) {
    seed = seed + 1;
  } else {
    let sum: number = 0;
    for (let ch: string of value) { sum = sum + strings.length(ch); }
    seed = seed + sum + 1;
  }
  let pick: number = pool[math.randomBelow(seed, pool.length())];
  let out: number[] = [];
  for (let u2: number of state.c_used) { out.push(u2); }
  out.push(pick);
