  return rebuildIdeas7(state, out, nextFit7(marked, state.time7, state.level7, state.at7 + 1), state.time7, state.level7);
}

function pickIdea7(state: AppState, index: number): AppState {
  if (index < 0 || index >= state.ideas7.length()) { return state; }
  return rebuildIdeas7(state, state.ideas7, index, state.time7, state.level7);
}

function setIdeaTime7(state: AppState, index: number): AppState {
  let at: number = state.at7;
  if (!fits7(state, index, state.level7, at)) { at = nextFit7(state, index, state.level7, 0); }
  return rebuildIdeas7(state, state.ideas7, at, index, state.level7);
}

function setIdeaLevel7(state: AppState, index: number): AppState {
  let at: number = state.at7;
  if (!fits7(state, state.time7, index, at)) { at = nextFit7(state, state.time7, index, 0); }
  return rebuildIdeas7(state, state.ideas7, at, state.time7, index);
}

function c_remaining(state: AppState): number[] {
  let out: number[] = [];
  let i: number = 0;
  while (i < state.ideas7.length()) {
    let seen: boolean = false;
    for (let p: number of state.c_picked) {
      if (p === i) { seen = true; }
    }
    if (!seen) { out.push(i); }
    i = i + 1;
  }
  return out;
}

function c_spin(state: AppState, value: number): AppState {
  if (state.c_speed > 0) {
    return state;
  }
  let left: number[] = c_remaining(state);
  if (left.length() === 0) {
    return state;
  }
  let seed: number = math.randomStep(state.c_seed);
  return {c_speed: 480 + math.randomBelow(seed, 300), c_seed: seed, c_landed: false, c_last: -1, choreCount: state.choreCount, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_angle: state.c_angle, c_picked: state.c_picked};
}

function c_frame(state: AppState, elapsedMs: number): AppState {
  if (state.c_speed <= 0) {
    return state;
  }
  let dt: number = math.min(elapsedMs, 50) / 1000;
  let angle: number = state.c_angle + state.c_speed * dt;
  angle = angle - 360 * math.floor(angle / 360);
  let speed: number = math.max(0, state.c_speed - 150 * dt);
  if (speed > 0) {
    return {c_angle: angle, c_speed: speed, choreCount: state.choreCount, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_seed: state.c_seed, c_picked: state.c_picked, c_last: state.c_last, c_landed: state.c_landed};
  }
  let left: number[] = c_remaining(state);
  let n: number = left.length();
  if (n === 0) {
    return {c_angle: angle, c_speed: 0, choreCount: state.choreCount, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_seed: state.c_seed, c_picked: state.c_picked, c_last: state.c_last, c_landed: state.c_landed};
  }
  let step: number = 360 / n;
  let under: number = 0 - angle;
  under = under - 360 * math.floor(under / 360);
  let slot: number = math.floor(under / step) % n;
  let chosen: number = left[slot];
  let picked: number[] = [];
  for (let p: number of state.c_picked) {
    picked.push(p);
  }
  picked.push(chosen);
  let last: number = chosen;
  if (picked.length() >= state.choreCount) {
    picked = [];
  }
  return {c_angle: angle, c_speed: 0, c_picked: picked, c_last: last, c_landed: true, choreCount: state.choreCount, ideas7: state.ideas7, at7: state.at7, time7: state.time7, level7: state.level7, c_seed: state.c_seed};
}

function c_tap(state: AppState, p: gfx.Pointer): AppState {
  if (p.phase === "up") {
    return c_spin(state, 0);
  }
  return state;
}

function c_px(a: number, r: number): number {
  return r * math.sin(a * math.pi() / 180);
}

function c_py(a: number, r: number): number {
  return 0 - r * math.cos(a * math.pi() / 180);
}

function c_draw(state: AppState): gfx.Shape[] {
  let left: number[] = c_remaining(state);
  let n: number = left.length();
  let wheel: gfx.Shape[] = [];
  if (n > 0) {
    let step: number = 360 / n;
    let i: number = 0;
    while (i < n) {
      let a0: number = i * step;
      let a1: number = a0 + step;
      let tone: string = "accent";
      if (i % 2 === 1) {
        tone = "#ffd54a";
      }
      wheel.push(gfx.polygon([0, 0, c_px(a0, 130), c_py(a0, 130), c_px(a0 + step / 2, 130), c_py(a0 + step / 2, 130),
        c_px(a1, 130), c_py(a1, 130)], tone));
      let label: string = state.ideas7[left[i]].title;
      if (label.length() > 14) {
        label = strings.substring(label, 0, 13) + "…";
      }
      wheel.push(gfx.group(c_px(a0 + step / 2, 88), c_py(a0 + step / 2, 88), a0 + step / 2, 1, 1,
        [gfx.text(0, 0, 13, "center", "ink", label, true)]));
      i = i + 1;
    }
  } else {
    wheel.push(gfx.circle(0, 0, 130, "surface"));
    wheel.push(gfx.text(0, 0, 16, "center", "muted", "Round complete", true));
  }
  wheel.push(gfx.circle(0, 0, 18, "surface"));
  let shapes: gfx.Shape[] = [];
  shapes.push(gfx.group(150, 150, state.c_angle, 1, 1, wheel));
  shapes.push(gfx.arc(150, 150, 130, 0, 360, 4, "ink"));
  shapes.push(gfx.polygon([150, 30, 138, 4, 162, 4], "danger"));
  return shapes;
}

