import * as ui from "std/ui"

@jsonable
class C_Song {
  title: string;
  played: boolean;
}

@jsonable
class AppState {
  songList: string;
  c_songs: C_Song[];
  c_draft: string;
  c_tried: boolean;
  c_current: string;
  c_round: number;
  c_seed: number;
  c_pulse: number;
}

function init(): AppState {
  return {songList: "", c_songs: [], c_draft: "", c_tried: false, c_current: "", c_round: 0, c_seed: 20260101, c_pulse: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_songList(state: AppState, value: string): AppState {
  return {songList: value, c_songs: state.c_songs, c_draft: state.c_draft, c_tried: state.c_tried, c_current: state.c_current, c_round: state.c_round, c_seed: state.c_seed, c_pulse: state.c_pulse};
}







function c_add(state: AppState, ignored: number): AppState {
  let name: string = strings.trim(state.c_draft);
  if (strings.length(name) === 0) {
    return {c_tried: true, songList: state.songList, c_songs: state.c_songs, c_draft: state.c_draft, c_current: state.c_current, c_round: state.c_round, c_seed: state.c_seed, c_pulse: state.c_pulse};
  }
  let out: C_Song[] = [];
  for (let s: C_Song of state.c_songs) {
    out.push(s);
  }
  out.push({title: name, played: false});
  return {c_songs: out, c_draft: "", c_tried: false, songList: state.songList, c_current: state.c_current, c_round: state.c_round, c_seed: state.c_seed, c_pulse: state.c_pulse};
}

function c_setDraft(state: AppState, value: string): AppState {
  return {c_draft: value, songList: state.songList, c_songs: state.c_songs, c_tried: state.c_tried, c_current: state.c_current, c_round: state.c_round, c_seed: state.c_seed, c_pulse: state.c_pulse};
}

function c_remove(state: AppState, value: number): AppState {
  let out: C_Song[] = [];
  let i: number = 0;
  while (i < state.c_songs.length()) {
    if (i !== value) {
      out.push(state.c_songs[i]);
    }
    i = i + 1;
  }
  let current: string = state.c_current;
  if (value >= 0 && value < state.c_songs.length()) {
    if (state.c_songs[value].title === current) {
      current = "";
    }
  }
  return {c_songs: out, c_current: current, songList: state.songList, c_draft: state.c_draft, c_tried: state.c_tried, c_round: state.c_round, c_seed: state.c_seed, c_pulse: state.c_pulse};
}

function c_clearPlayed(state: AppState, ignored: number): AppState {
  let out: C_Song[] = [];
  for (let s: C_Song of state.c_songs) {
    out.push({title: s.title, played: false});
  }
  return {c_songs: out, c_current: "", c_round: 0, songList: state.songList, c_draft: state.c_draft, c_tried: state.c_tried, c_seed: state.c_seed, c_pulse: state.c_pulse};
}

function c_shuffle(state: AppState, ignored: number): AppState {
  let total: number = state.c_songs.length();
  if (total === 0) {
    return state;
  }
  let left: number = 0;
  let i: number = 0;
  while (i < total) {
    if (!state.c_songs[i].played) {
      left = left + 1;
    }
    i = i + 1;
  }
  let round: number = state.c_round;
  let base: C_Song[] = [];
  if (left === 0) {
    for (let s: C_Song of state.c_songs) {
      base.push({title: s.title, played: false});
    }
    round = round + 1;
    left = total;
  } else {
    for (let s: C_Song of state.c_songs) {
      base.push(s);
    }
  }
  let seed: number = math.randomStep(state.c_seed);
  let pick: number = math.randomBelow(seed, left);
  let seen: number = 0;
  let chosen: number = 0;
  let j: number = 0;
  while (j < base.length()) {
    if (!base[j].played) {
      if (seen === pick) {
        chosen = j;
      }
      seen = seen + 1;
    }
    j = j + 1;
  }
  let out: C_Song[] = [];
  let k: number = 0;
  while (k < base.length()) {
    if (k === chosen) {
      out.push({title: base[k].title, played: true});
    } else {
      out.push(base[k]);
    }
    k = k + 1;
  }
  return {c_songs: out, c_current: base[chosen].title, c_round: round, c_seed: seed, c_pulse: state.c_pulse + 1, songList: state.songList, c_draft: state.c_draft, c_tried: state.c_tried};
}

function c_draw(state: AppState): gfx.Shape[] {
  let shapes: gfx.Shape[] = [];
  shapes.push(gfx.rect(0, 0, 320, 200, "surface"));
  let total: number = state.c_songs.length();
  let played: number = 0;
  let i: number = 0;
  while (i < total) {
    if (state.c_songs[i].played) {
      played = played + 1;
    }
    i = i + 1;
  }
  let cx: number = 160;
  let cy: number = 100;
  shapes.push(gfx.circle(cx, cy, 62, "accent"));
  shapes.push(gfx.circle(cx, cy, 52, "surface"));
  let label: string = "Add songs";
  if (total > 0) {
    label = ui.numberToString(played) + " / " + ui.numberToString(total);
  }
  shapes.push(gfx.text(cx, cy - 6, 22, "center", "ink", label, true));
  shapes.push(gfx.text(cx, cy + 20, 12, "center", "muted", "played", false));
  let dots: number = total;
  if (dots > 12) {
    dots = 12;
  }
  let d: number = 0;
  while (d < dots) {
    let a: number = d * (360 / dots);
    let px: number = cx + 84 * math.sin(a * math.pi() / 180);
    let py: number = cy - 84 * math.cos(a * math.pi() / 180);
    let tone: string = "line";
    if (state.c_songs[d].played) {
      tone = "accent";
    }
    shapes.push(gfx.circle(px, py, 6, tone));
    d = d + 1;
  }
  if (strings.length(state.c_current) > 0) {
    shapes.push(gfx.text(cx, 186, 14, "center", "ink", state.c_current, true));
  }
  return shapes;
}

function c_tap(state: AppState, p: gfx.Pointer): AppState {
  if (p.phase === "up") {
    return c_shuffle(state, 0);
  }
  return state;
}

function view(state: AppState): ui.View {
  let sections: ui.View[] = [];
  sections.push(ui.Header("default", "Random Song Picker", "NO REPEATS", "Shuffle through your songs without hearing one twice", ""));
  {
    sections.push(ui.Section("content", "", "", [ui.TextField("default", "Songs", state.songList, "set_songList")]));
  }
  {
  let c_rows: ui.View[] = [];
  let c_i: number = 0;
  while (c_i < state.c_songs.length()) {
    let c_s: C_Song = state.c_songs[c_i];
    let c_mark: string = "Not played yet";
    if (c_s.played) {
      c_mark = "Played";
    }
    c_rows.push(ui.ListItem("default", c_s.title, c_mark, "", "c_remove", c_i, true, ""));
    c_i = c_i + 1;
  }
  let c_left: number = 0;
  let c_j: number = 0;
  while (c_j < state.c_songs.length()) {
    if (!state.c_songs[c_j].played) {
      c_left = c_left + 1;
    }
    c_j = c_j + 1;
  }
  let c_hasSongs: boolean = state.c_songs.length() > 0;
  sections.push(ui.Section("content", "Shuffle picker", "Never repeats until every song has played", [
    ui.Surface("default", 320, 200, "c_draw", "", "c_tap"),
    ui.When(strings.length(state.c_current) > 0, ui.Motion("pop", state.c_pulse, [
      ui.Text("title", "Now playing: " + state.c_current)
    ])),
    ui.When(c_hasSongs, ui.Text("caption", ui.numberToString(c_left) + " left in this round")),
    ui.ActionBar("default", [
      ui.Button("primary", "Shuffle", "c_shuffle", 0, c_hasSongs),
      ui.Button("secondary", "Reset played", "c_clearPlayed", 0, c_hasSongs)
    ])
  ]));
  sections.push(ui.Section("content", "Your songs", "Add the songs you want in the shuffle", [
    ui.TextField("default", "Song title", state.c_draft, "c_setDraft"),
    ui.When(state.c_tried, ui.Text("danger", "Enter a song title first.")),
    ui.ActionBar("end", [
      ui.Button("primary", "Add song", "c_add", 0, true)
    ]),
    ui.When(!c_hasSongs, ui.EmptyState("default", "No songs yet", "Add a song above to start shuffling.", "", "", "list")),
    ui.When(c_hasSongs, ui.ListGroup("default", "", c_rows))
  ]));
  }
  return ui.AppTheme("playful", "", sections);
}

