import * as ui from "std/ui"

@jsonable
class AppState {
  rounds: number;
  c_round: number;
  c_score: number;
  c_animal: number;
  c_guess: string;
  c_typed: string;
  c_status: number;
  c_seed: number;
  c_anim: number;
  c_animMs: number;
  c_used: number[];
  c_usedCount: number;
  c_checked: boolean;
}

function init(): AppState {
  return {rounds: 5, c_round: 0, c_score: 0, c_animal: -1, c_guess: "", c_typed: "", c_status: 0, c_seed: 20261105, c_anim: 0, c_animMs: 0, c_used: [], c_usedCount: 0, c_checked: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_rounds(state: AppState, value: number): AppState {
  return {rounds: value, c_round: state.c_round, c_score: state.c_score, c_animal: state.c_animal, c_guess: state.c_guess, c_typed: state.c_typed, c_status: state.c_status, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount, c_checked: state.c_checked};
}







function c_names(): string[] {
  return ["LION", "TIGER", "ELEPHANT", "GIRAFFE", "PENGUIN", "DOLPHIN", "KANGAROO", "OCTOPUS", "SQUIRREL", "CROCODILE", "BUTTERFLY", "RHINOCEROS"];
}

function c_hints(): string[] {
  return ["Big cat with a mane", "Striped big cat", "Huge, with a trunk", "Tallest land animal", "A bird that swims", "A clever sea mammal", "Hopping pouched animal", "Eight-armed sea creature", "Bushy-tailed climber", "Toothy river reptile", "Colourful winged insect", "Horned heavyweight"];
}

function c_shuffleWord(word: string, seed: number): string {
  let chars: string[] = [];
  for (let ch: string of word) {
    chars.push(ch);
  }
  let s: number = seed;
  let i: number = chars.length() - 1;
  while (i > 0) {
    s = math.randomStep(s);
    let j: number = math.randomBelow(s, i + 1);
    let tmp: string = chars[i];
    chars[i] = chars[j];
    chars[j] = tmp;
    i = i - 1;
  }
  let out: string = "";
  for (let ch: string of chars) {
    out = out + ch;
  }
  return out;
}

function c_startRound(state: AppState, seedIn: number): AppState {
  let names: string[] = c_names();
  let total: number = names.length();
  let seed: number = seedIn;
  let pick: number = math.randomBelow(seed, total);
  let guard: number = 0;
  while (guard < total && state.c_usedCount < total) {
    let found: boolean = false;
    for (let u: number of state.c_used) {
      if (u === pick) { found = true; }
    }
    if (!found) { guard = total; } else {
      seed = math.randomStep(seed);
      pick = math.randomBelow(seed, total);
      guard = guard + 1;
    }
  }
  let used: number[] = [];
  for (let u: number of state.c_used) {
    used.push(u);
  }
  used.push(pick);
  return {c_animal: pick, c_guess: "", c_typed: "", c_status: 0, c_seed: seed, c_anim: state.c_anim + 1, c_animMs: 0, c_used: used, c_usedCount: used.length(), c_checked: false, rounds: state.rounds, c_round: state.c_round, c_score: state.c_score};
}

function c_newGame(state: AppState, value: number): AppState {
  let seed: number = math.randomStep(state.c_seed);
  let empty: number[] = [];
  let base: AppState = {c_round: 0, c_score: 0, c_animal: -1, c_guess: "", c_typed: "", c_status: 0, c_seed: seed, c_anim: state.c_anim + 1, c_animMs: 0, c_used: empty, c_usedCount: 0, c_checked: false, rounds: state.rounds};
  return c_startRound(base, seed);
}

function c_next(state: AppState, value: number): AppState {
  if (state.c_round + 1 >= state.rounds) {
    return state;
  }
  let seed: number = math.randomStep(state.c_seed);
  let base: AppState = {c_round: state.c_round + 1, c_seed: seed, c_anim: state.c_anim + 1, c_animMs: 0, rounds: state.rounds, c_score: state.c_score, c_animal: state.c_animal, c_guess: state.c_guess, c_typed: state.c_typed, c_status: state.c_status, c_used: state.c_used, c_usedCount: state.c_usedCount, c_checked: state.c_checked};
  return c_startRound(base, seed);
}

function c_tapLetter(state: AppState, value: number): AppState {
  if (state.c_animal < 0 || state.c_status !== 0) {
    return state;
  }
  let word: string = c_names()[state.c_animal];
  let scrambled: string = c_shuffleWord(word, state.c_animal + 7);
  if (value < 0 || value >= scrambled.length()) {
    return state;
  }
  let ch: string = strings.substring(scrambled, value, value + 1);
  return {c_guess: state.c_guess + ch, rounds: state.rounds, c_round: state.c_round, c_score: state.c_score, c_animal: state.c_animal, c_typed: state.c_typed, c_status: state.c_status, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount, c_checked: state.c_checked};
}

function c_back(state: AppState, value: number): AppState {
  if (state.c_guess.length() === 0) {
    return state;
  }
  return {c_guess: strings.substring(state.c_guess, 0, state.c_guess.length() - 1), rounds: state.rounds, c_round: state.c_round, c_score: state.c_score, c_animal: state.c_animal, c_typed: state.c_typed, c_status: state.c_status, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount, c_checked: state.c_checked};
}

function c_clear(state: AppState, value: number): AppState {
  return {c_guess: "", rounds: state.rounds, c_round: state.c_round, c_score: state.c_score, c_animal: state.c_animal, c_typed: state.c_typed, c_status: state.c_status, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount, c_checked: state.c_checked};
}

function c_type(state: AppState, value: string): AppState {
