    return state;
  }
  let word: string = c_names()[state.c_animal];
  let attempt: string = state.c_guess;
  if (state.c_typed.length() > 0) {
    attempt = state.c_typed;
  }
  if (attempt.length() === 0) {
    return {c_checked: true, rounds: state.rounds, c_round: state.c_round, c_score: state.c_score, c_animal: state.c_animal, c_guess: state.c_guess, c_typed: state.c_typed, c_status: state.c_status, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount};
  }
  if (strings.toUpperCase(attempt) === word) {
    return {c_status: 1, c_score: state.c_score + 1, c_checked: true, rounds: state.rounds, c_round: state.c_round, c_animal: state.c_animal, c_guess: state.c_guess, c_typed: state.c_typed, c_seed: state.c_seed, c_anim: state.c_anim, c_animMs: state.c_animMs, c_used: state.c_used, c_usedCount: state.c_usedCount};
