    return shapes;
  }
  let word: string = c_names()[state.c_animal];
  let scrambled: string = c_shuffleWord(word, state.c_animal + 7);
  let n: number = scrambled.length();
  let tileW: number = 300 / n;
  let settle: number = math.min(1, state.c_animMs / 900);
  let i: number = 0;
  while (i < n) {
    let ch: string = strings.substring(scrambled, i, i + 1);
    let cx: number = tileW * i + tileW / 2;
    let cy: number = 130;
    let wobble: number = (1 - settle) * 40 * math.sin((state.c_animMs / 120) + i * 1.3);
    let rot: number = (1 - settle) * 180 * math.sin((state.c_animMs / 200) + i);
    let tone: string = "accent";
    if (state.c_status === 1) { tone = "success"; }
    if (state.c_status === 2) { tone = "danger"; }
    let tile: gfx.Shape[] = [];
    tile.push(gfx.roundRect(0 - tileW / 2 + 4, -28, tileW - 8, 56, 8, tone));
    tile.push(gfx.text(0, 0, 24, "center", "onAccent", ch, true));
    shapes.push(gfx.group(cx, cy + wobble, rot, 1, 1, tile));
    i = i + 1;
  }
  let shown: string = state.c_guess;
  if (state.c_typed.length() > 0) { shown = state.c_typed; }
  shapes.push(gfx.text(150, 190, 18, "center", "ink", shown, true));
  return shapes;
}

