function c_shuffleWord(word: string, seed: number): string {
  let chars: string[] = [];
  for (let ch: string of word) {
    chars.push(ch);
  }
  let s: number = seed;
  let i: number = chars.length() - 1;
  while (i > 0) {
    s = math.randomStep(s);
    let j: number = math.randomBelow(s, i + 1);
    let tmp: string = chars[i];
    chars[i] = chars[j];
    chars[j] = tmp;
    i = i - 1;
  }
  let out: string = "";
  for (let ch: string of chars) {
    out = out + ch;
  }
  return out;
}

function c_startRound(state: AppState, seed: number): AppState {
  let names: string[] = c_names();
  let total: number = names.length();
  let pick: number = math.randomBelow(seed, total);
  let guard: number = 0;
  while (guard < total && state.c_usedCount < total) {
    let found: boolean = false;
    for (let u: number of state.c_used) {
      if (u === pick) { found = true; }
    }
    if (!found) { guard = total; } else {
      seed = math.randomStep(seed);
      pick = math.randomBelow(seed, total);
      guard = guard + 1;
    }
  }
  let used: number[] = [];
  for (let u: number of state.c_used) {
    used.push(u);
  }
  used.push(pick);
  return {c_animal: pick, c_guess: "", c_typed: "", c_status: 0, c_seed: seed, c_anim: state.c_anim + 1, c_animMs: 0, c_used: used, c_usedCount: used.length(), c_checked: false__PASSTHROUGH__};
