class AppState {
  startWord: string;
  endWord: string;
  entries: LogEntry[];
  draft_word: string;
  removedEntries: LogEntry[];
  removedAt: number;
}

function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {startWord: "", endWord: "", entries: emptyEntries, draft_word: "", removedEntries: emptyEntries, removedAt: -1};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_startWord(state: AppState, value: string): AppState {
  return {startWord: value, endWord: state.endWord, entries: state.entries, draft_word: state.draft_word, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function set_endWord(state: AppState, value: string): AppState {
  return {endWord: value, startWord: state.startWord, entries: state.entries, draft_word: state.draft_word, removedEntries: state.removedEntries, removedAt: state.removedAt};
}



function set_draft_word(state: AppState, value: string): AppState {
  return {draft_word: value, startWord: state.startWord, endWord: state.endWord, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_word) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {word: strings.trim(state.draft_word), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_word: "", startWord: state.startWord, endWord: state.endWord, removedAt: state.removedAt};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, startWord: state.startWord, endWord: state.endWord, draft_word: state.draft_word};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
