  c_total: number;
  c_found: string;
  c_foundScores: number;
  c_foundCount: number;
  c_msg: string;
  settingsOpen: boolean;
}

function init(): AppState {
  return {elapsedMs: 0, running: false, finished: false, gridSizeIndex: 1, roundLengthIndex: 1, c_letters: "", c_gridN: 0, c_seed: 20261101, c_path: [], c_word: "", c_lastWord: "", c_lastScore: 0, c_total: 0, c_found: "", c_foundScores: 0, c_foundCount: 0, c_msg: "", settingsOpen: false};
