function c_draw(state: AppState): gfx.Shape[] {
  let shapes: gfx.Shape[] = [];
  let n: number = c_gridSize(state);
  let size: number = 300;
  let cell: number = size / n;
  shapes.push(gfx.roundRect(0, 0, size, size, 12, "surface"));
  let letters: string = state.c_letters;
  if (state.c_gridN !== n || strings.length(letters) !== n * n) {
    letters = c_makeLetters(n, state.c_seed);
  }
  let i: number = 0;
  while (i < n * n) {
    let row: number = math.floor(i / n);
    let col: number = i % n;
    let x: number = col * cell;
    let y: number = row * cell;
    let picked: boolean = c_inPath(state.c_path, i);
    let fill: string = "background";
    if (picked) { fill = "accent"; }
    shapes.push(gfx.roundRect(x + 3, y + 3, cell - 6, cell - 6, 8, fill));
    let ink: string = "ink";
    if (picked) { ink = "onAccent"; }
    shapes.push(gfx.text(x + cell / 2, y + cell / 2, cell * 0.42, "center", ink, strings.toUpperCase(c_letterAt(letters, i)), true));
    i = i + 1;
  }
  return shapes;
}

