  let next: number = state.elapsedMs + elapsedMs;
  if (next < total) { return {elapsedMs: next, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_path: state.c_path, c_word: state.c_word, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, c_msg: state.c_msg, settingsOpen: state.settingsOpen}; }
  return {elapsedMs: total, running: false, finished: true, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_path: state.c_path, c_word: state.c_word, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, c_msg: state.c_msg, settingsOpen: state.settingsOpen};
