}

function c_inDictionary(word: string): boolean {
  let dict: string[] = c_dictionary();
  let i: number = 0;
  while (i < dict.length()) {
    if (dict[i] === word) { return true; }
    i = i + 1;
  }
  return false;
}

function c_letterAt(letters: string, index: number): string {
  if (index < 0 || index >= strings.length(letters)) { return ""; }
  return strings.substring(letters, index, index + 1);
}

function c_makeLetters(n: number, seed: number): string {
  let alphabet: string = "abcdefghijklmnopqrstuvwxyz";
  let out: string = "";
  let s: number = seed;
  let i: number = 0;
  while (i < n * n) {
    s = math.randomStep(s);
    let pick: number = math.randomBelow(s, 26);
    out = out + strings.substring(alphabet, pick, pick + 1);
    i = i + 1;
  }
  return out;
}

function c_ensure(state: AppState, ignored: number): AppState {
  let n: number = c_gridSize(state);
  if (state.c_gridN === n && strings.length(state.c_letters) === n * n) {
    return state;
  }
  let seed: number = math.randomStep(state.c_seed);
  let letters: string = c_makeLetters(n, seed);
  let empty: number[] = [];
  return {c_letters: letters, c_gridN: n, c_seed: seed, c_path: empty, c_word: "", c_msg: "", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, settingsOpen: state.settingsOpen};
}

function c_shuffle(state: AppState, ignored: number): AppState {
  let n: number = c_gridSize(state);
  let seed: number = math.randomStep(state.c_seed);
  let letters: string = c_makeLetters(n, seed);
  let empty: number[] = [];
  return {c_letters: letters, c_gridN: n, c_seed: seed, c_path: empty, c_word: "", c_msg: "", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, settingsOpen: state.settingsOpen};
}

function c_adjacent(a: number, b: number, n: number): boolean {
  let ar: number = math.floor(a / n);
  let ac: number = a % n;
  let br: number = math.floor(b / n);
  let bc: number = b % n;
  let dr: number = math.abs(ar - br);
  let dc: number = math.abs(ac - bc);
  if (dr === 0 && dc === 0) { return false; }
  return dr <= 1 && dc <= 1;
}

function c_inPath(path: number[], index: number): boolean {
  let i: number = 0;
  while (i < path.length()) {
    if (path[i] === index) { return true; }
    i = i + 1;
  }
  return false;
}

function c_pathWord(letters: string, path: number[]): string {
  let out: string = "";
  let i: number = 0;
  while (i < path.length()) {
    out = out + c_letterAt(letters, path[i]);
    i = i + 1;
  }
  return out;
}

function c_cellAt(x: number, y: number, n: number, size: number): number {
  let cell: number = size / n;
  let col: number = math.floor(x / cell);
  let row: number = math.floor(y / cell);
  if (col < 0 || col >= n || row < 0 || row >= n) { return -1; }
  return row * n + col;
}

function c_pointer(state: AppState, p: gfx.Pointer): AppState {
  let n: number = c_gridSize(state);
  if (state.c_gridN !== n) { return state; }
  if (state.finished) { return state; }
  let size: number = 300;
  let index: number = c_cellAt(p.x, p.y, n, size);
  if (p.phase === "down") {
    if (index < 0) { return state; }
    let fresh: number[] = [];
    fresh.push(index);
    return {c_path: fresh, c_word: c_pathWord(state.c_letters, fresh), c_msg: "", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, settingsOpen: state.settingsOpen};
  }
  if (p.phase === "move") {
    if (index < 0) { return state; }
    let count: number = state.c_path.length();
    if (count === 0) { return state; }
    let last: number = state.c_path[count - 1];
    if (index === last) { return state; }
    if (count >= 2 && state.c_path[count - 2] === index) {
      let shorter: number[] = [];
      let i: number = 0;
      while (i < count - 1) {
        shorter.push(state.c_path[i]);
        i = i + 1;
      }
      return {c_path: shorter, c_word: c_pathWord(state.c_letters, shorter), elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, c_msg: state.c_msg, settingsOpen: state.settingsOpen};
    }
    if (c_inPath(state.c_path, index)) { return state; }
    if (!c_adjacent(last, index, n)) { return state; }
    let grown: number[] = [];
    let j: number = 0;
    while (j < count) {
      grown.push(state.c_path[j]);
      j = j + 1;
    }
    grown.push(index);
    return {c_path: grown, c_word: c_pathWord(state.c_letters, grown), elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, c_msg: state.c_msg, settingsOpen: state.settingsOpen};
  }
  if (p.phase === "up" || p.phase === "cancel") {
    let word: string = state.c_word;
    let empty: number[] = [];
    if (strings.length(word) < c_minWord()) {
      return {c_path: empty, c_word: "", c_msg: "", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, settingsOpen: state.settingsOpen};
    }
    if (!c_inDictionary(word)) {
      return {c_path: empty, c_word: "", c_msg: "\"" + word + "\" is not in the dictionary", elapsedMs: state.elapsedMs, running: state.running, finished: state.finished, gridSizeIndex: state.gridSizeIndex, roundLengthIndex: state.roundLengthIndex, c_letters: state.c_letters, c_gridN: state.c_gridN, c_seed: state.c_seed, c_lastWord: state.c_lastWord, c_lastScore: state.c_lastScore, c_total: state.c_total, c_found: state.c_found, c_foundScores: state.c_foundScores, c_foundCount: state.c_foundCount, settingsOpen: state.settingsOpen};
