    order.push(i);
    i = i + 1;
  }
  let seed: number = state.c_seed;
  let j: number = n - 1;
  while (j > 0) {
    seed = math.randomStep(seed);
    let k: number = math.randomBelow(seed, j + 1);
    let tmp: number = order[j];
    order[j] = order[k];
    order[k] = tmp;
    j = j - 1;
  }
  return {c_puzzles: puzzles, c_order: order, c_round: 0, c_guess: "", c_revealed: false, c_correct: false, c_started: true, c_seed: seed__PASSTHROUGH__};
