function init(): AppState {
  let emptyEntries: LogEntry[] = [];
  return {roundsPerGame: 10, entries: emptyEntries, draft_guess: "", removedEntries: emptyEntries, removedAt: -1, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_roundsPerGame(state: AppState, value: number): AppState {
  return {roundsPerGame: value, entries: state.entries, draft_guess: state.draft_guess, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}



function set_draft_guess(state: AppState, value: string): AppState {
  return {draft_guess: value, roundsPerGame: state.roundsPerGame, entries: state.entries, removedEntries: state.removedEntries, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function addEntry(state: AppState, ignored: number): AppState {
  if (strings.trim(state.draft_guess) === "") { return state; }
  let none: LogEntry[] = [];
  let entry: LogEntry = {guess: strings.trim(state.draft_guess), minute: time.hourOfDay() * 60 + time.minuteOfHour()};
  let out: LogEntry[] = [];
  for (let e: LogEntry of state.entries) { out.push(e); }
  out.push(entry);
  return {entries: out, removedEntries: none, draft_guess: "", roundsPerGame: state.roundsPerGame, removedAt: state.removedAt, settingsOpen: state.settingsOpen};
}

function removeEntry(state: AppState, value: number): AppState {
  let out: LogEntry[] = [];
  let gone: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i !== value) { out.push(state.entries[i]); } else { gone.push(state.entries[i]); }
    i = i + 1;
  }
  return {entries: out, removedEntries: gone, removedAt: value, roundsPerGame: state.roundsPerGame, draft_guess: state.draft_guess, settingsOpen: state.settingsOpen};
}

function undoRemove(state: AppState, ignored: number): AppState {
  if (state.removedEntries.length() === 0) { return state; }
  let out: LogEntry[] = [];
  let none: LogEntry[] = [];
  let i: number = 0;
  while (i < state.entries.length()) {
    if (i === state.removedAt) { out.push(state.removedEntries[0]); }
    out.push(state.entries[i]);
    i = i + 1;
  }
  if (state.removedAt >= state.entries.length()) { out.push(state.removedEntries[0]); }
  return {entries: out, removedEntries: none, removedAt: -1, roundsPerGame: state.roundsPerGame, draft_guess: state.draft_guess, settingsOpen: state.settingsOpen};
}

function expireUndo(state: AppState, elapsedMs: number): AppState {
  let none: LogEntry[] = [];
