  return {hintLetters: 3, c_countries: [], c_guess: "", c_index: 0, c_attempted: false, c_feedback: "", c_right: 0, c_wrong: 0};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_hintLetters(state: AppState, value: number): AppState {
  return {hintLetters: value, c_countries: state.c_countries, c_guess: state.c_guess, c_index: state.c_index, c_attempted: state.c_attempted, c_feedback: state.c_feedback, c_right: state.c_right, c_wrong: state.c_wrong};
}







function c_makeList(): C_Country[] {
  let out: C_Country[] = [];
  out.push({name: "France", done: false, correct: false});
  out.push({name: "Brazil", done: false, correct: false});
  out.push({name: "Japan", done: false, correct: false});
  out.push({name: "Kenya", done: false, correct: false});
  out.push({name: "Canada", done: false, correct: false});
  out.push({name: "Norway", done: false, correct: false});
  out.push({name: "Mexico", done: false, correct: false});
  out.push({name: "India", done: false, correct: false});
  return out;
}

function c_ensure(state: AppState): C_Country[] {
  if (state.c_countries.length() === 0) {
    return c_makeList();
  }
  return state.c_countries;
}

function c_hint(name: string, letters: number): string {
  let n: number = letters;
  if (n < 1) { n = 1; }
  if (n > name.length()) { n = name.length(); }
  let out: string = "";
  let i: number = 0;
  while (i < name.length()) {
    if (i < n) {
      out = out + strings.substring(name, i, i + 1);
    } else {
      out = out + "_";
    }
    i = i + 1;
  }
  return out;
}

function c_setGuess(state: AppState, value: string): AppState {
  return {c_guess: value, hintLetters: state.hintLetters, c_countries: state.c_countries, c_index: state.c_index, c_attempted: state.c_attempted, c_feedback: state.c_feedback, c_right: state.c_right, c_wrong: state.c_wrong};
}

function c_check(state: AppState, ignored: number): AppState {
  let list: C_Country[] = c_ensure(state);
  let idx: number = state.c_index;
  if (idx >= list.length()) {
    return {c_countries: list, c_attempted: true, c_feedback: "All countries guessed. Start again to replay.", hintLetters: state.hintLetters, c_guess: state.c_guess, c_index: state.c_index, c_right: state.c_right, c_wrong: state.c_wrong};
  }
  let typed: string = strings.trim(state.c_guess);
  if (typed.length() === 0) {
    return {c_countries: list, c_attempted: true, c_feedback: "Type a country name first.", hintLetters: state.hintLetters, c_guess: state.c_guess, c_index: state.c_index, c_right: state.c_right, c_wrong: state.c_wrong};
  }
  let target: C_Country = list[idx];
  let ok: boolean = strings.toLowerCase(typed) === strings.toLowerCase(target.name);
  let out: C_Country[] = [];
  let i: number = 0;
  while (i < list.length()) {
    let c: C_Country = list[i];
    if (i === idx) {
      out.push({name: c.name, done: true, correct: ok});
    } else {
      out.push({name: c.name, done: c.done, correct: c.correct});
    }
    i = i + 1;
  }
  let msg: string = "";
  if (ok) {
    msg = "Correct! It was " + target.name + ".";
  } else {
    msg = "Not quite. It was " + target.name + ".";
  }
  let right: number = state.c_right;
  let wrong: number = state.c_wrong;
  if (ok) { right = right + 1; } else { wrong = wrong + 1; }
  return {c_countries: out, c_index: idx + 1, c_guess: "", c_attempted: true, c_feedback: msg, c_right: right, c_wrong: wrong, hintLetters: state.hintLetters};
}

function c_restart(state: AppState, ignored: number): AppState {
  return {c_countries: c_makeList(), c_index: 0, c_guess: "", c_attempted: false, c_feedback: "", c_right: 0, c_wrong: 0, hintLetters: state.hintLetters};
}

function view(state: AppState): ui.View {
