@jsonable class C_Puzzle {
  day: number;
  letters: string;
  numbers: string;
  acrossClues: string;
  downClues: string;
}

@jsonable
class AppState {
  c_day: number;
  c_letters: string;
  c_numbers: string;
  c_acrossClues: string;
  c_downClues: string;
  c_sel: number;
  c_dir: string;
  c_typed: string;
  c_checked: boolean;
  c_solved: boolean;
  c_msg: string;
}

function init(): AppState {
  return {c_day: 0, c_letters: "", c_numbers: "", c_acrossClues: "", c_downClues: "", c_sel: 0, c_dir: "across", c_typed: "", c_checked: false, c_solved: false, c_msg: ""};
