function c_load(state: AppState, ignored: number): AppState {
  let today: number = time.daysSinceEpoch();
  let p: C_Puzzle = c_pickPuzzle(today);
  let blank: string = "";
  let i: number = 0;
  while (i < 25) { blank = blank + " "; i = i + 1; }
  return {
    c_day: today,
    c_letters: blank,
    c_numbers: p.numbers,
    c_acrossClues: p.acrossClues,
    c_downClues: p.downClues,
    c_sel: 0,
    c_dir: "across",
    c_typed: "",
    c_checked: false,
    c_solved: false,
    c_msg: ""
  };
}

function c_tapCell(state: AppState, value: number): AppState {
  if (state.c_letters.length() !== 25) { return {c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_dir: state.c_dir, c_typed: state.c_typed, c_checked: state.c_checked, c_solved: state.c_solved, c_msg: state.c_msg}; }
  return {c_sel: value, c_msg: "", c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_dir: state.c_dir, c_typed: state.c_typed, c_checked: state.c_checked, c_solved: state.c_solved};
}

function c_toggleDir(state: AppState, ignored: number): AppState {
  let d: string = "across";
  if (state.c_dir === "across") { d = "down"; }
  return {c_dir: d, c_msg: "", c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_typed: state.c_typed, c_checked: state.c_checked, c_solved: state.c_solved};
}

function c_type(state: AppState, value: string): AppState {
  if (state.c_letters.length() !== 25) { return {c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_dir: state.c_dir, c_typed: state.c_typed, c_checked: state.c_checked, c_solved: state.c_solved, c_msg: state.c_msg}; }
  let v: string = strings.toUpperCase(strings.trim(value));
  if (v.length() === 0) { return {c_typed: "", c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_dir: state.c_dir, c_checked: state.c_checked, c_solved: state.c_solved, c_msg: state.c_msg}; }
  let ch: string = strings.substring(v, 0, 1);
  let letters: string = state.c_letters;
  let out: string = "";
  let i: number = 0;
  while (i < 25) {
    if (i === state.c_sel) { out = out + ch; } else { out = out + strings.substring(letters, i, i + 1); }
    i = i + 1;
  }
  let next: number = state.c_sel + 1;
  if (next > 24) { next = 24; }
  return {c_letters: out, c_sel: next, c_typed: "", c_checked: false, c_solved: false, c_msg: "", c_day: state.c_day, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_dir: state.c_dir};
}

function c_check(state: AppState, ignored: number): AppState {
  if (state.c_letters.length() !== 25) { return {c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_dir: state.c_dir, c_typed: state.c_typed, c_checked: state.c_checked, c_solved: state.c_solved, c_msg: state.c_msg}; }
  let p: C_Puzzle = c_pickPuzzle(state.c_day);
  let sol: string = p.letters;
  let ok: boolean = true;
  let i: number = 0;
  while (i < 25) {
    if (strings.substring(state.c_letters, i, i + 1) !== strings.substring(sol, i, i + 1)) { ok = false; }
    i = i + 1;
  }
  let m: string = "Not quite — keep going.";
  if (ok) { m = "Solved! Come back tomorrow for a new puzzle."; }
  return {c_checked: true, c_solved: ok, c_msg: m, c_day: state.c_day, c_letters: state.c_letters, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_sel: state.c_sel, c_dir: state.c_dir, c_typed: state.c_typed};
}

function c_clear(state: AppState, ignored: number): AppState {
  let blank: string = "";
  let i: number = 0;
  while (i < 25) { blank = blank + " "; i = i + 1; }
  return {c_letters: blank, c_sel: 0, c_checked: false, c_solved: false, c_msg: "", c_day: state.c_day, c_numbers: state.c_numbers, c_acrossClues: state.c_acrossClues, c_downClues: state.c_downClues, c_dir: state.c_dir, c_typed: state.c_typed};
}



