import * as ui from "std/ui"

@jsonable
class Item {
  label: string;
  detail: string;
  done: boolean;
}

@jsonable
class AppState {
  servings: number;
  items7: Item[];
  settingsOpen: boolean;
}

function init(): AppState {
  let items7: Item[] = [
    {label: "Monday: Oatmeal with berries", detail: "swap", done: false},
    {label: "Tuesday: Scrambled eggs", detail: "swap", done: false},
    {label: "Wednesday: Yogurt", detail: "swap", done: false},
    {label: "Thursday: Pancakes", detail: "swap", done: false},
    {label: "Friday: Smoothie bowl", detail: "swap", done: false},
    {label: "Saturday: Avocado toast", detail: "swap", done: false},
    {label: "Sunday: Waffles", detail: "swap", done: false}
  ];
  return {servings: 2, items7: items7, settingsOpen: false};
}

function share(a: number, b: number): number {
  if (b === 0) { return 0; }
  return a / b;
}



function set_servings(state: AppState, value: number): AppState {
  return {servings: value, items7: state.items7, settingsOpen: state.settingsOpen};
}







function toggle7(state: AppState, index: number): AppState {
  let out: Item[] = [];
  let i: number = 0;
  while (i < state.items7.length()) {
    let it: Item = state.items7[i];
    if (i === index) {
      out.push({label: it.label, detail: it.detail, done: !it.done});
    } else {
      out.push(it);
    }
    i = i + 1;
  }
  return {items7: out, servings: state.servings, settingsOpen: state.settingsOpen};
